import subprocess
from ta_emil_cli_aatrace_parser.tracecollector import TraceCollector
from robot.api import logger


class BinTraceCollector(object):
    """
    This class is used for enb BIN trace collecting and storing in user defined location.
    Collecting is possible only with passing msg_id because downloading SACKs is NOT a
    precondition for this collecting.
    """

    @staticmethod
    def bin_trace_start(msg_hex=None, node_id=None, alias='DEFAULT', trace_output_file='CLI_TRACE_BIN_DEFAULT',
                        trace_output_dir='/home/ute/enb_trace_testing'):
        """
            Start tracing procedure with requested filters, trace result is writen to file
            only after using of stop_cli_aatrace_tracing() method from this class
            :param alias      - alias used to create trace bin path, unique per test case
            :param msg_hex    - string with messages hex representation where ',' is separator
            :param node_id    - string with specific node_id where ',' is separator
            :param trace_output_file - filename for collected BIN
            :param trace_output_dir - directory where to save collected trace BIN file
            :return: None

            +---------------------------------------------------------------------------------+
            |  Examples                                                                       |
            +=================================================================================+
            |                                                                                 |
            |  WHEN YOU USE HEX:                                                              |
            |                                                                                 |
            | Start BIN Trace Collection                                                      |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x426A-0x426B, 0x3308, 0x3422-0x3444, 0x2000                    |
            |                                                                                 |
            |  WHEN YOU USE NODE_ID:                                                          |
            |                                                                                 |
            | Start BIN Trace Collection                                                      |
            |   ...   alias=enb_trace_1                                                       |
            |   ...   msg_hex=0x4e3a                                                          |
            |   ...   node_id=0x124a, 0x224a                                                  |
            +---------------------------------------------------------------------------------+
        """

        trace_file = trace_output_dir + '/' + trace_output_file + '.bin'
        logger.debug('Prepare to start BIN trace collection for alias {} with {} messages and output_file {}'
                     .format(alias, msg_hex, trace_file))

        parsed_filters = TraceCollector.generate_cli_filters(msg_hex=msg_hex)

        if node_id:
            aashell_data = TraceCollector.get_platform_info_from_aashell()
            node_ids = TraceCollector.parse_node_id_list(node_id)
            platform = TraceCollector.get_hw_platform_type(aashell_data)
        else:
            platform, node_ids = TraceCollector.get_hw_platform_and_core_ids_for_uec()

        cmd = TraceCollector.build_cli_aatrace_command(platform, node_ids, trace_file, parsed_filters)

        TraceCollector.check_required_os_resources(trace_output_dir, trace_file)
        cli_process = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        logger.debug('cli_aatrace command: {} cli_aatrace pid {}'.format(cmd, cli_process.pid))

        return trace_file
